"""Profundización ISE · Parte 2: Autoridad, poder y ambientes sanos (id: ise-2). Orientaciones 9 a 13."""
from ise_base import (u, q, ise, C_CARTA_PD, C_CARTA_CHILE, C_VELM, C_CYE, R_ISE, R_PREV, NOTA_VIGENCIA, CARTA_PD, EG, CV, DCE, CYE, VELM, PREV)

P2 = [
    u("Comunidad fraterna: la autoridad como servicio (orientación 9)",
      "Comprender la orientación 9 del ISE, sobre las relaciones fraternas en la comunidad, el ejercicio de la autoridad como servicio, la participación y la corrección fraterna.",
      "La orientación 9 cierra el grupo del buen trato y mira a la comunidad entera: cómo se colabora, cómo se decide, cómo se ejerce la autoridad y cómo se recibe la crítica. Es una de las más ricas del documento y la que más directamente responde al llamado del papa Francisco a superar el clericalismo. Aunque nombra la autoridad, se aplica a cualquiera que coordina algo: un consejo, un grupo, un coro, una catequesis.",
      "Piensa en la última decisión importante de tu comunidad o grupo. ¿Quién la tomó? ¿A quién se consultó? ¿Cómo se informó?",
      ["Explicar los siete estándares de la orientación 9.", "Reconocer el culto a la persona y otras formas de autoridad mal ejercida.", "Practicar la consulta transparente y la corrección fraterna."],
      [("Orientación 9: promover relaciones fraternas y respetuosas en la comunidad",
        "- **a.** Buscar relaciones de cooperación, con especial esfuerzo hacia quienes son de trato difícil.\n- **b.** Respetar los estilos de vida, las costumbres, la historia y las visiones de las personas de la comunidad.\n- **c.** Ejercer la autoridad con prudencia, como servicio y sin beneficio propio.\n- **d.** Promover la participación de la mujer y de la vocación laical en las instancias eclesiales y de decisión.\n- **e.** Facilitar los acuerdos mediante consultas transparentes y buscar colaboración en las decisiones.\n- **f.** Evitar los cultos personales, centrados en uno mismo o en otros, y corregir esas conductas cuando aparecen.\n- **g.** Acoger con apertura la crítica y la corrección fraterna, y propiciar ambientes donde sean posibles."),
       ("Autoridad que sirve",
        "Para el ISE, la autoridad se ejerce **con prudencia, como servicio y sin beneficio propio** (9.c). Señales de una autoridad sana:\n\n- explica sus decisiones y acepta preguntas;\n- reparte responsabilidades y deja hacer;\n- consulta antes de decidir lo que afecta a todos;\n- tiene períodos definidos y prepara su relevo;\n- puede ser contradicha sin consecuencias.\n\nY señales de una autoridad enferma: decide sola, se rodea de incondicionales, castiga con indiferencia o exclusión a quien discrepa, se considera indispensable, mezcla sus intereses con los de la comunidad.\n\nEl estándar **9.b** agrega un cuidado para quien llega a una comunidad con algún cargo: antes de cambiar las cosas, conocer y respetar su historia y sus costumbres."),
       ("Participación de las mujeres y de los laicos",
        "El estándar **9.d** es explícito: promover la participación **de la mujer y de la vocación laical** en las instancias eclesiales y de **decisión**. No habla solo de colaborar en tareas, sino de estar donde se decide.\n\nPreguntas para una comunidad: ¿quiénes integran el consejo pastoral y el económico?, ¿cómo fueron elegidos?, ¿cuántas mujeres y cuántos jóvenes hay?, ¿sus opiniones cambian alguna vez una decisión?\n\nEl **9.e** pide **consultas transparentes**: que se sepa qué se consulta, a quiénes, qué se hará con las respuestas y qué se decidió finalmente. Consultar para luego hacer lo que ya estaba resuelto destruye la confianza."),
       ("Culto a la persona y corrección fraterna",
        "La experiencia de la Iglesia en Chile mostró cuánto daño puede hacer una figura a la que nadie se atreve a cuestionar. Por eso el **9.f** pide evitar los **cultos personales**, hacia uno mismo o hacia otros, y corregirlos cuando aparecen.\n\nSeñales: «el padre (o el coordinador, o la asesora) siempre tiene la razón»; un grupo que gira en torno a una persona y no a Jesús; quienes la critican son tratados como traidores; se le perdona lo que a nadie más; su palabra pesa más que el Evangelio o que las normas de la Iglesia.\n\nEl antídoto está en el **9.g**: una comunidad donde la **crítica y la corrección fraterna** son posibles y bienvenidas, también hacia quienes tienen autoridad. No basta decir «mi puerta está abierta»: hay que crear momentos concretos para evaluar y escuchar.")],
      ("El fundador",
       "Un movimiento juvenil fue creado hace quince años por Rodrigo, un laico carismático. Él elige a los coordinadores, define los temas y es el único que predica en los retiros. Los jóvenes repiten sus frases y llevan poleras con ellas. Cuando una coordinadora propone elegir al equipo por votación y evaluar los retiros, Rodrigo le dice que «le falta espíritu» y deja de invitarla a las reuniones.",
       ["¿Qué estándares de la orientación 9 se incumplen?", "¿Qué señales de culto a la persona reconoces?", "¿Qué podrían hacer los demás coordinadores y a quién podrían acudir?"]),
      [["Clericalismo", "Forma desviada de entender la autoridad en la Iglesia, que concentra el poder en unos pocos y anula la participación del Pueblo de Dios; puede darse también entre laicos."], ["Culto a la persona", "Admiración acrítica hacia un líder, a quien no se puede cuestionar."], ["Corrección fraterna", "Decir a un hermano, con verdad y caridad, lo que debe cambiar, y dejarse decir lo mismo."]],
      ("Marcos 10,42-45 · No será así entre ustedes",
       "Jesús contrasta a los jefes que dominan con sus discípulos: el que quiera ser grande, que se haga servidor, porque el Hijo del hombre no vino a ser servido sino a servir. Es la medida de toda autoridad en la Iglesia."),
      ("¿Cómo reaccionas cuando alguien cuestiona una decisión tuya?", "Pide por quienes ejercen autoridad en tu comunidad, para que sirvan con humildad.", "Esta semana, pide a alguien de confianza que te diga con franqueza algo que deberías mejorar en tu servicio."),
      [ise("orientación 9", "Pide ejercer la autoridad como servicio y sin beneficio propio, promover la participación de la mujer y de los laicos en las decisiones, consultar con transparencia, evitar los cultos personales y acoger la corrección fraterna."),
       ("Evangelii gaudium 102-104", EG, "Señala que un excesivo clericalismo mantiene a los laicos al margen de las decisiones, y pide ampliar los espacios para una presencia femenina más incisiva en la Iglesia, también donde se toman decisiones importantes."),
       C_CARTA_PD],
      ["¿Cómo se toman las decisiones en tu comunidad?", "¿Qué lugar tienen las mujeres y los jóvenes donde se decide?", "¿Hay alguien a quien nadie se atreve a contradecir?", "¿Cuándo fue la última vez que tu grupo evaluó a sus coordinadores?"],
      "Hagan una **evaluación de la autoridad** en su grupo: cada uno responde por escrito y sin nombre tres preguntas (¿me siento escuchado?, ¿sé cómo y quién decide?, ¿puedo discrepar sin consecuencias?). Un tercero reúne las respuestas y las presenta. El equipo coordinador escucha sin defenderse y propone dos cambios.",
      ["Lee en el ISE la orientación 9.", "Revisa quiénes integran los espacios de decisión de tu comunidad.", "Realiza la evaluación anónima en tu grupo.", "Acuerda períodos y relevo para los cargos."],
      "Señor Jesús, que lavaste los pies de tus discípulos: libra a tu Iglesia de toda forma de dominio. Danos autoridades que sirvan, comunidades que participen y hermanos que se corrijan con amor. Amén.",
      "Nadie en la Iglesia está por encima de la corrección fraterna.",
      ("Tres prácticas contra el culto a la persona",
       "1. **Rotación:** cargos con períodos definidos y relevo preparado.\n2. **Equipo:** nada importante depende de una sola persona; se predica, se forma y se decide entre varios.\n3. **Evaluación:** toda actividad y todo servicio se evalúan, con participación de quienes los reciben."),
      [R_ISE, ("Carta del papa Francisco al Pueblo de Dios", CARTA_PD, "Su llamado a decir no a toda forma de clericalismo.")]),

    u("El poder en la relación de servicio (orientación 10)",
      "Comprender la orientación 10 del ISE sobre los efectos del desequilibrio de poder en una relación de servicio, primera del grupo dedicado a los ambientes sanos y la prevención.",
      "Con la orientación 10 comienza el grupo más extenso del ISE: la *promoción de ambientes sanos y respetuosos de la dignidad de toda persona y la prevención de situaciones abusivas*. El documento no empieza por las normas, sino por la raíz: el **poder**. Todo abuso, antes de ser sexual, económico o de conciencia, es un abuso de poder. Quien sirve en la Iglesia siempre tiene poder, lo sepa o no.",
      "Haz una lista de las personas sobre las que tienes alguna influencia en tu servicio (por tu edad, tu cargo, tu conocimiento o la confianza que te tienen). ¿Eras consciente de ese poder?",
      ["Explicar los cuatro estándares de la orientación 10.", "Identificar las fuentes de poder en una relación pastoral.", "Reconocer el abuso de poder y de conciencia, y la función del «tercero»."],
      [("Orientación 10: comprender los efectos del desequilibrio de poder en una relación de servicio",
        "- **a.** Reflexionar sobre el sentido del propio servicio, fundado en el bien de los demás y no en motivaciones egoístas.\n- **b.** Reconocer la propia posición de poder y ejercerlo con sentido fraterno y compasivo, nunca para beneficio propio.\n- **c.** Monitorear las relaciones asimétricas inevitables, evaluar su impacto y aceptar la corrección fraterna.\n- **d.** Reconocer cuándo una relación de servicio se vuelve insegura o ineficaz, y resolverlo dialogando con un tercero."),
       ("De dónde viene el poder de quien sirve",
        "Una relación es **asimétrica** cuando una de las partes tiene más poder que la otra. En la pastoral eso es inevitable y no es malo en sí mismo; lo grave es ignorarlo.\n\n| Fuente de poder | Ejemplo |\n|---|---|\n| **El cargo** | Coordinador, catequista, asesor, párroco |\n| **La edad** | Un adulto ante un niño; un joven de 20 ante uno de 14 |\n| **Lo sagrado** | Quien habla «en nombre de Dios», celebra, bendice, acompaña |\n| **El conocimiento** | Quien sabe más de la fe, de la persona o de la institución |\n| **La confianza y el afecto** | Aquel a quien se admira o se quiere |\n| **La necesidad del otro** | Quien da una ayuda, un sacramento, un cupo, un certificado |\n\nA mayor diferencia de poder, **menor capacidad del otro para decir que no**. Por eso el consentimiento de quien depende de mí, me admira o me teme no me autoriza a nada: la responsabilidad de cuidar el límite es siempre de quien tiene más poder."),
       ("Abuso de poder y abuso de conciencia",
        "Hay **abuso de poder** cuando alguien usa su posición para su propio beneficio o para someter a otro: humillar, exigir favores, castigar al que discrepa, decidir sobre la vida ajena.\n\nEl **abuso de conciencia** es una forma particular y muy grave en ambientes religiosos: alguien se apropia del lugar que solo corresponde a Dios y a la conciencia de la persona. Dicta lo que el otro debe pensar, sentir y decidir; controla sus relaciones, lecturas y tiempos; exige obediencia en nombre de Dios; aísla y pide secreto.\n\nEl papa Francisco los nombra juntos, abusos sexuales, de poder y de conciencia, porque suelen ir encadenados: quien ha sometido la conciencia de alguien ha quitado ya casi todas sus defensas. El ISE pide acoger las denuncias de las tres clases (orientación 14)."),
       ("Monitorear, y el papel del tercero",
        "El estándar **10.c** pide *monitorear* las relaciones asimétricas: revisarlas cada cierto tiempo y dejar que otros las miren. El **10.d** añade que, cuando una relación de servicio se vuelve insegura o ineficaz, se resuelve **dialogando con un tercero**.\n\nEl *tercero* es una idea central en la prevención: nadie se cuida solo ni es buen juez de sí mismo. Un tercero puede ser el asesor, otro dirigente, un acompañante espiritual, el encargado de prevención. En la práctica:\n\n- Se sirve **en equipo**, no en solitario.\n- Alguien más **sabe** a quién acompaño y cómo.\n- Si noto que una relación se me complica (me busca demasiado, me incomoda, me atrae, depende de mí), **lo hablo** con un tercero en vez de manejarlo a solas.\n- Si observo algo preocupante en otro, **no miro para el lado**: las líneas guía *Cuidado y Esperanza* consideran la formación de terceros que intervienen como una estrategia básica de prevención.")],
      ("«Ella quería»",
       "Un dirigente de 23 años inicia una relación sentimental con una joven de 16 de su grupo de confirmación. Se escriben en secreto. Cuando otro dirigente se lo hace notar, responde: «No hay nada malo; ella fue la que empezó y está feliz. Además no soy cura». El grupo se divide entre quienes lo defienden y quienes se incomodan.",
       ["¿Qué fuentes de poder tiene el dirigente sobre la joven?", "¿Por qué el «ella quería» no resuelve el problema, según la orientación 10?", "¿Qué debería hacer el dirigente que lo notó?"]),
      [["Relación asimétrica", "Relación en la que una parte tiene más poder que la otra por su cargo, edad, conocimiento o rol espiritual."], ["Abuso de conciencia", "Sometimiento de la libertad interior de una persona en nombre de Dios o de la autoridad espiritual."], ["Tercero", "Persona distinta de las dos partes de una relación, que la observa, acompaña o interviene para cuidar."]],
      ("1 Pedro 5,2-3 · No como dominadores",
       "Pedro pide a los responsables de las comunidades apacentar el rebaño de Dios de buen grado, no por ganancia ni como quienes dominan a los que se les confiaron, sino siendo modelos del rebaño."),
      ("¿Sobre quién tienes poder? ¿Cómo lo usas?", "Pide un corazón libre del deseo de dominar y de ser necesario.", "Esta semana, cuenta a un tercero de confianza a quiénes acompañas y cómo lo haces."),
      [ise("orientación 10", "Pide reconocer la propia posición de poder, ejercerla con sentido fraterno y nunca en beneficio propio, monitorear las relaciones asimétricas y acudir a un tercero cuando una relación se vuelve insegura."),
       C_CARTA_PD,
       ("Christus vivit 98", CV, "Recoge la enseñanza de que el clericalismo es una tentación permanente, que interpreta el ministerio recibido como un poder que se ejerce más que como un servicio gratuito y generoso.")],
      ["¿Qué fuentes de poder tienes tú en tu servicio?", "¿Has visto usar a Dios o la fe para controlar a alguien?", "¿Quién es tu «tercero»? ¿Con quién hablas de tu servicio?", "¿Qué haría tu grupo si un dirigente iniciara una relación con alguien a su cargo?"],
      "Dibujen el **mapa de poder** de su grupo: quién tiene autoridad sobre quién y por qué fuente (cargo, edad, rol espiritual, confianza). Marquen las relaciones más asimétricas y acuerden, para cada una, un resguardo: quién actúa como tercero y cómo se revisa.",
      ["Lee en el ISE la orientación 10.", "Identifica tus fuentes de poder.", "Elige a un tercero y conversa con él sobre tu servicio.", "Acuerda con tu equipo qué hacer ante relaciones afectivas entre dirigentes y miembros del grupo."],
      "Señor Jesús, que siendo Dios te despojaste de tu rango: enséñanos a usar el poder que nos confías solo para levantar, nunca para dominar. Que nadie quede sometido por nuestra causa. Amén.",
      "Quien tiene más poder tiene siempre la responsabilidad del límite.",
      ("Regla práctica para equipos de dirigentes",
       "Muchas comunidades acuerdan por escrito que no se inician relaciones de pareja entre un dirigente o asesor y un miembro del grupo que tiene a su cargo; y que, si surge un interés genuino entre personas adultas, se conversa con el equipo y uno de los dos deja ese rol. Con menores de edad no hay excepción posible. El ISE no fija esta regla con detalle, pero es una aplicación directa de la orientación 10."),
      [R_ISE, ("Carta del papa Francisco al Pueblo de Dios", CARTA_PD, "Abusos sexuales, de poder y de conciencia.")]),

    u("Fronteras físicas y emocionales (orientación 11)",
      "Comprender y aplicar los diez estándares de la orientación 11 del ISE, sobre el respeto de las fronteras físicas y emocionales de niños, niñas, jóvenes y adultos vulnerables.",
      "La orientación 11 es la más concreta del ISE y la que más se consulta en la vida pastoral diaria. Describe cómo se cuida el límite con niños, jóvenes y adultos vulnerables: los lugares, el afecto, los regalos, las redes sociales, el alcohol, los espacios no habilitados. Conviene leerla despacio, estándar por estándar.",
      "Recuerda una situación en que un adulto traspasó un límite tuyo cuando eras niño o adolescente (un abrazo que no querías, una pregunta invasiva, una broma sobre tu cuerpo). ¿Pudiste decir algo? No necesitas compartirla.",
      ["Explicar los diez estándares de la orientación 11.", "Aplicarlos a situaciones frecuentes de la pastoral con menores.", "Distinguir lo que dice el ISE de lo que regulan las Buenas Prácticas y los protocolos diocesanos."],
      [("Orientación 11: respetar las fronteras físicas y emocionales de niños y niñas, jóvenes y adultos vulnerables",
        "- **a.** Reconocer que una relación insegura no atiende las necesidades de quien se ayuda o lo pone en riesgo, y ponerle término si es necesario.\n- **b.** Respetar la integridad física y mental, el espacio emocional y la privacidad de cada persona.\n- **c.** Tratar a los demás de forma fraterna, coherente y amable, evitando la familiaridad excesiva.\n- **d.** Servir en lugares seguros, abiertos y visibles, y no en espacios restringidos o solitarios.\n- **e.** Cuidar las expresiones de afecto, físicas y emocionales, según la sensibilidad y necesidad de la otra persona, sin buscar la propia satisfacción.\n- **f.** Evitar que el afecto o los obsequios generen favoritismo, con especial atención a menores y personas vulnerables.\n- **g.** No ejercer ni tolerar en el propio entorno maltrato físico, psicológico o sexual.\n- **h.** Usar los medios y las redes sociales con los mismos criterios que la relación presencial.\n- **i.** No ofrecer alcohol ni otras sustancias controladas sin prescripción a menores o personas vulnerables, ni consumirlas en su presencia.\n- **j.** Tomar medidas especiales al servir en espacios no habilitados para la pastoral: acompañamiento de adultos y autorización de padres o tutores si hay menores."),
       ("Lugares, afecto y regalos (11.c a 11.f)",
        "**Lugares (11.d).** Las conversaciones personales con un menor se tienen en espacios abiertos o visibles: una sala con la puerta abierta o con ventana, un patio, un rincón del salón donde otros puedan ver. No en una oficina cerrada, un auto, una casa particular o un lugar apartado. Lo mismo vale, con prudencia, para adultos vulnerables.\n\n**Afecto (11.e).** El cariño es parte de la vida pastoral; el criterio es de quién es la necesidad. Un saludo o un abrazo breve, en público, que el otro acepta con naturalidad, responde a su necesidad. Abrazos prolongados, caricias, cosquillas, sentar a alguien en las rodillas, masajes o besos responden a la necesidad del adulto. Ante la duda, no. Y si un niño o joven no quiere un gesto, se respeta sin comentarios.\n\n**Familiaridad excesiva (11.c).** Confidencias sobre la propia vida afectiva, apodos íntimos, bromas de doble sentido o tratar a un menor como «mi mejor amigo» borran la diferencia de roles.\n\n**Regalos y favoritismo (11.f).** Los regalos individuales, los privilegios y la atención exclusiva hacia un niño o joven son una señal de alerta conocida: así suele comenzar un proceso de acercamiento abusivo. Los regalos, si los hay, son para todos y a la vista."),
       ("Maltrato, redes sociales y alcohol (11.g a 11.i)",
        "**No ejercer ni tolerar (11.g).** El estándar tiene dos verbos. No basta con no maltratar: tampoco se **tolera** en el propio entorno. Gritos, humillaciones, castigos físicos, «pruebas» o ritos de iniciación degradantes, burlas por el cuerpo o la orientación de alguien: quien los ve y calla, los está tolerando.\n\n**Redes sociales (11.h).** El ISE da un criterio simple: **lo mismo que en lo presencial**. Si no conversaría a solas con un menor a medianoche en una pieza cerrada, tampoco lo hago por mensajes privados. De ahí se derivan prácticas que muchas diócesis y grupos adoptan: comunicarse por grupos o canales institucionales y con más de un adulto presente, en horarios razonables, sin pedir ni enviar fotos personales, sin contenidos inadecuados y sin pedir secreto.\n\n**Alcohol y otras sustancias (11.i).** No se ofrecen a menores ni a personas vulnerables, y el adulto que sirve **no consume en su presencia**. Esto incluye campamentos, misiones, celebraciones de fin de año y asados del grupo."),
       ("Espacios no habilitados, y lo que el ISE no detalla (11.j)",
        "Cuando la pastoral sale de sus lugares habituales (una casa, un paseo, un campamento, una misión), el **11.j** pide medidas especiales: **adultos que acompañen** y **autorización de padres o tutores** cuando participan menores.\n\nEl ISE da criterios generales y **no regula en detalle** asuntos como el transporte, las pernoctaciones, el uso de baños y duchas o la publicación de fotografías de menores. Para eso remite al documento **Buenas Prácticas para ambientes sanos y seguros en la Iglesia** (orientación 13.c) y a los protocolos de cada diócesis, que suelen establecer, por ejemplo: dormitorios separados para adultos y menores, y para varones y mujeres; al menos dos adultos responsables en cada actividad; autorizaciones escritas; y que ningún adulto quede a solas con un menor en un vehículo o una habitación.\n\nAntes de cualquier actividad con menores fuera de la parroquia, pide el protocolo vigente de tu diócesis.\n\n" + NOTA_VIGENCIA)],
      ("El tío buena onda",
       "Felipe, catequista de 28 años, es el favorito de los niños de primera comunión. A uno de ellos, Benjamín, de 10 años, le regala un celular usado «porque su familia no puede», lo lleva en auto a su casa después de la catequesis y le escribe por las noches para saber cómo está. La mamá está agradecida. Otra catequista siente que algo no está bien, pero piensa: «Es tan bueno con los niños; ¿y si lo estoy juzgando mal?».",
       ["¿Qué estándares de la orientación 11 se están incumpliendo, aunque no haya ocurrido ningún delito?", "¿Qué debe hacer la catequista con su inquietud, según la orientación 10.d?", "¿Por qué actuar ahora protege también a Felipe?"]),
      [["Frontera", "Límite físico o emocional que protege la intimidad y la integridad de una persona."], ["Persona vulnerable", "Quien, por su edad, condición o situación, tiene limitada su capacidad de resistir o de defenderse."], ["Favoritismo", "Trato preferente hacia una persona mediante atención exclusiva, regalos o privilegios; es una señal de alerta en la prevención."]],
      ("Mateo 18,5-6 · El que recibe a un niño en mi nombre",
       "Jesús se identifica con los pequeños: quien recibe a uno de ellos en su nombre, lo recibe a él. Y pronuncia una de sus palabras más duras contra quien haga tropezar a uno solo de ellos."),
      ("¿Cuidas los límites de los niños y jóvenes como querrías que cuidaran los de tus propios hijos o hermanos?", "Ora por los niños, niñas y jóvenes que han sido heridos en la Iglesia.", "Esta semana, revisa con tu equipo los lugares donde conversan con menores y corrige lo que no sea visible."),
      [ise("orientación 11", "Pide servir en lugares seguros, abiertos y visibles; cuidar las expresiones de afecto y los regalos; no ejercer ni tolerar maltrato; usar las redes sociales con los mismos criterios que la relación presencial; no consumir alcohol ante menores; y contar con adultos acompañantes y autorización de los padres en espacios no habilitados."),
       C_CYE,
       ("Christus vivit 95-97", CV, "Reconoce el daño de los abusos cometidos por clérigos y otros miembros de la Iglesia y pide adoptar medidas rigurosas de prevención, que impidan que se repitan.")],
      ["¿Dónde conversa tu equipo con niños y jóvenes? ¿Son lugares visibles?", "¿Qué gestos de afecto son habituales en tu grupo? ¿Todos se sienten cómodos?", "¿Cómo se comunican los dirigentes con los menores por redes?", "¿Conoces el protocolo de tu diócesis para salidas y campamentos?"],
      "Recorran físicamente los lugares donde se hace pastoral con menores (salones, oficinas, patios, baños, sacristía) con la orientación 11 en la mano. Anoten qué espacios no son visibles y qué habría que cambiar: una ventana en una puerta, una oficina que no se usa a solas, un turno de adultos. Entreguen la lista al párroco o al consejo.",
      ["Lee en el ISE la orientación 11 completa.", "Recorre los espacios pastorales de tu comunidad.", "Consigue las Buenas Prácticas y el protocolo de tu diócesis.", "Acuerda con tu equipo las reglas de comunicación digital con menores."],
      "Señor Jesús, que abrazaste a los niños y los bendijiste: haz de nuestras comunidades lugares donde los pequeños estén seguros. Danos delicadeza en el trato, claridad en los límites y valentía para no callar. Amén.",
      "En lo digital, lo mismo que en lo presencial; y en la duda, el límite.",
      ("La prueba de la transparencia",
       "Antes de un gesto, un regalo, un mensaje o un encuentro con un menor, pregúntate: **¿lo haría igual delante de sus padres, de mi equipo y de mi párroco?** Si la respuesta es no, o si necesito que no se sepa, no lo hago. Y si otro dirigente me hace notar un límite, se lo agradezco: me está cuidando."),
      [R_ISE, R_PREV, ("Cuidado y Esperanza. Líneas Guía de la CECh", CYE, "Capítulo IV: prevención y ambientes sanos y seguros.")]),

    u("Acompañar con resguardos (orientación 12)",
      "Comprender la orientación 12 del ISE, que establece los resguardos del acompañamiento espiritual y de otras formas de ayuda pastoral.",
      "Acompañar a otra persona en su vida y en su fe es uno de los servicios más valiosos de la Iglesia, y también uno de los más delicados: quien acompaña entra en la intimidad del otro y adquiere sobre él una influencia muy grande. La orientación 12 pide que este servicio se haga con **preparación, límites claros y supervisión**. Vale para el acompañamiento espiritual formal y para toda ayuda pastoral: la escucha de un catequista, la conversación de un dirigente con un joven, la visita a un enfermo.",
      "¿Has acompañado alguna vez a alguien que pasaba por un momento difícil? ¿Te sentiste preparado? ¿Con quién lo conversaste después?",
      ["Explicar los estándares de la orientación 12.", "Distinguir entre escuchar, acompañar espiritualmente y hacer terapia.", "Reconocer los propios límites y saber derivar."],
      [("Orientación 12: cuidar, con los resguardos adecuados, los procesos de acompañamiento espiritual y otras formas de ayuda pastoral",
        "- **a.** Acompañar espiritualmente solo con preparación, informando a la persona la finalidad, los objetivos y la modalidad.\n- **b.** Recibir formación inicial y permanente, y reconocer las propias limitaciones.\n- **c.** Mantener un registro de profesionales a los que derivar a las personas cuando sea necesario.\n- **d.** Usar instrumentos de psicometría solo si se está acreditado y con supervisión profesional.\n- **e.** Recibir acompañamiento espiritual frecuente y supervisión de las propias dinámicas emocionales.\n\n*Particulares para la autoridad eclesiástica:*\n\n- **f.** Velar por la aplicación de estos puntos en seminarios y casas de formación.\n- **g.** Asegurar que los acompañantes tengan formación, supervisión y acompañamiento, y que exista una entidad que los certifique."),
       ("Tres niveles que no se deben confundir",
        "| Nivel | Qué es | Quién puede |\n|---|---|---|\n| **Escucha fraterna** | Estar disponible, escuchar sin juzgar, orar con la persona, animar | Todo agente pastoral, con criterio y límites |\n| **Acompañamiento espiritual** | Proceso periódico para ayudar a reconocer la acción de Dios y discernir | Quien tiene formación específica y supervisión (12.a, 12.b, 12.e) |\n| **Atención profesional** | Psicoterapia, psiquiatría, asesoría legal o social | Solo profesionales (12.c) |\n\nUn dirigente juvenil de 19 años puede y debe **escuchar**. No le corresponde dirigir la conciencia de nadie ni tratar una depresión, un duelo complicado o las consecuencias de un abuso. El estándar **12.d** añade un límite preciso: los tests psicológicos y de personalidad no son un juego de retiro; solo los aplica quien está acreditado."),
       ("Un acompañamiento sano",
        "El estándar **12.a** pide informar a la persona **para qué** es el acompañamiento, **qué** se busca y **cómo** será. En la práctica, un encuadre claro:\n\n- **Libertad:** la persona elige a su acompañante y puede dejarlo cuando quiera, sin dar explicaciones.\n- **Lugar y tiempo:** encuentros en un lugar visible y adecuado (orientación 11.d), con duración y frecuencia acordadas; no a cualquier hora ni por mensajes interminables.\n- **Límites del rol:** el acompañante no decide por el otro, no pide obediencia y no se convierte en su amigo exclusivo ni en su confidente mutuo.\n- **Reserva sin secreto dañino:** lo conversado es reservado, pero nunca se promete callar un abuso o un riesgo grave para la vida de alguien.\n- **Fuero interno y gobierno separados:** quien acompaña la conciencia de una persona no usa lo que sabe para tomar decisiones sobre ella.\n\nSeñales de un acompañamiento **enfermo**: el acompañante exige exclusividad, desalienta otras relaciones, pide secreto, decide vocación, pareja o estudios, hace sentir culpa por discrepar, o busca contacto físico."),
       ("Nadie acompaña sin ser acompañado",
        "El estándar **12.e** es quizás el más importante: quien acompaña debe **recibir** acompañamiento espiritual frecuente y **supervisión** de sus propias dinámicas emocionales. Escuchar el dolor ajeno remueve la historia propia; el afecto y la admiración de quien es acompañado pueden confundir; el cansancio hace bajar la guardia.\n\nY el **12.c** pide tener a mano un **registro de profesionales** para derivar: psicólogos, médicos, abogados, trabajadores sociales, canonistas. Derivar no es abandonar: es reconocer el propio límite (12.b) y seguir caminando junto a la persona mientras otro atiende lo que yo no puedo.\n\nSituaciones en que **siempre** se deriva o se pide ayuda de inmediato: riesgo de suicidio o autolesión, revelación de abuso, violencia en la familia, consumo problemático, trastornos de la alimentación, síntomas graves de salud mental.")],
      ("El consejero del grupo",
       "Tomás, de 21 años, es el dirigente «al que todos le cuentan sus cosas». Una noche, Javiera, de 16, le escribe que ya no quiere vivir y le pide que no le cuente a nadie. Tomás conversa con ella hasta las tres de la mañana, le promete guardar el secreto y decide acompañarla él mismo, escribiéndole todos los días. A las dos semanas está agotado y asustado.",
       ["¿Qué estándares de la orientación 12 ayudan a ver lo que Tomás debió hacer distinto?", "¿Por qué no podía prometer secreto?", "¿Qué debe hacer ahora, y con quién?"]),
      [["Acompañamiento espiritual", "Ayuda periódica que una persona preparada ofrece a otra para reconocer la acción de Dios en su vida y discernir."], ["Supervisión", "Revisión del propio servicio de acompañamiento con una persona competente, para cuidar a quien es acompañado y a quien acompaña."], ["Encuadre", "Acuerdo explícito sobre la finalidad, el lugar, el tiempo y los límites de un acompañamiento."]],
      ("Lucas 24,13-35 · Jesús en el camino de Emaús",
       "El Resucitado se acerca a dos discípulos desanimados, camina a su paso, pregunta, escucha, ilumina con la Escritura y parte el pan. Cuando lo reconocen, desaparece: no los ata a sí mismo, los devuelve libres a la comunidad."),
      ("¿Acompañas para que el otro sea libre, o para que te necesite?", "Agradece por quienes te han acompañado bien en tu vida.", "Esta semana, busca a alguien que te acompañe a ti, si aún no lo tienes."),
      [ise("orientación 12", "Pide acompañar solo con preparación, informar a la persona la finalidad y la modalidad, reconocer los propios límites, tener un registro de profesionales para derivar y recibir uno mismo acompañamiento y supervisión."),
       ("Evangelii gaudium 169-171", EG, "Habla del arte del acompañamiento: aprender a quitarse las sandalias ante la tierra sagrada del otro, con una escucha respetuosa y compasiva que haga crecer en libertad."),
       ("Christus vivit 246", CV, "Recoge las cualidades que los jóvenes esperan de quien los acompaña: que sea un cristiano comprometido, que no juzgue, que escuche, que reconozca sus límites y que no pretenda ser perfecto ni decidir por ellos.")],
      ["¿Quiénes acompañan a otros en tu comunidad? ¿Qué preparación tienen?", "¿Sabes a qué profesionales o instituciones derivar?", "¿Has prometido alguna vez un secreto que no debías guardar?", "¿Quién te acompaña a ti?"],
      "Elaboren el **registro de derivación** que pide el estándar 12.c: profesionales e instituciones de salud mental, apoyo social, orientación legal y canónica, y teléfonos de emergencia, con nombre, contacto, horario y costo. Agreguen una hoja de «situaciones en que siempre se pide ayuda» y entréguenla a cada dirigente.",
      ["Lee en el ISE la orientación 12.", "Distingue en tu servicio: ¿escucho, acompaño o estoy haciendo algo que no me corresponde?", "Arma el registro de derivación.", "Busca acompañamiento para ti."],
      "Señor, compañero de camino, que te acercaste a los discípulos de Emaús sin imponerte: enséñanos a escuchar con respeto, a reconocer nuestros límites y a conducir a cada persona hacia ti y no hacia nosotros. Amén.",
      "Nadie acompaña bien si no es acompañado.",
      ("Qué decir cuando alguien pide secreto",
       "«Lo que me cuentes lo voy a cuidar. Pero si se trata de algo que te pone en peligro a ti o a otra persona, o de alguien que te está haciendo daño, voy a tener que pedir ayuda a quien pueda protegerte, y te voy a avisar antes de hacerlo.» Decirlo **antes** de que la persona hable es honesto y evita traicionar su confianza después. La parte 3 detalla cómo actuar ante una revelación."),
      [R_ISE, ("Deus caritas est 31", DCE, "Quienes sirven en la caridad necesitan, además de preparación profesional, una «formación del corazón».")]),

    u("La política de prevención y las estructuras de apoyo (orientación 13 y consideraciones finales)",
      "Comprender la orientación 13 del ISE y el conjunto de estructuras, normas, estándares y orientaciones con que la Iglesia en Chile previene los abusos y acompaña a las víctimas.",
      "El ISE no está solo: es una pieza de un sistema mayor. La orientación 13 pide a todo agente pastoral **adherir a la política de prevención** de la Iglesia, y las consideraciones finales del documento describen ese sistema: quiénes son responsables, qué normas rigen, qué estándares se aplican. Conocerlo permite saber a quién acudir y qué exigir.",
      "Sin buscar: ¿sabes quién es la persona encargada de recibir denuncias en tu diócesis y cómo contactarla? Anota lo que sabes; al final de la sesión lo completarás.",
      ["Explicar los tres estándares de la orientación 13.", "Describir las estructuras nacionales y diocesanas de prevención.", "Distinguir normas, estándares y orientaciones, y ubicar el ISE entre ellos."],
      [("Orientación 13: adherir a la política de prevención de abusos en la Iglesia católica",
        "- **a.** Participar en los programas de formación en prevención de abusos de las líneas guía *Cuidado y Esperanza*.\n- **b.** Conocer y adherir a los documentos que rigen los casos de abuso sexual de menores, y a las normas propias de las comunidades religiosas cuando corresponda.\n- **c.** Conocer, aplicar y cumplir el documento de **Buenas Prácticas** aprobado por la Conferencia Episcopal.\n\nEn concreto: todo agente pastoral que trabaja con menores debería haber hecho el **curso de prevención** que ofrece su diócesis, conocer los documentos y aplicar las buenas prácticas. No es un trámite: es condición para servir."),
       ("Las estructuras: quién es responsable",
        "**A nivel nacional:**\n\n- El **Consejo Nacional de Prevención de Abusos y Acompañamiento de Víctimas**, creado en 2011, asesora a los obispos en las políticas de prevención y de ayuda a las víctimas.\n- El **Departamento de Prevención de Abusos**, creado en 2018 en la Secretaría General de la Conferencia Episcopal, ejecuta esas políticas y puede recibir denuncias conforme a la normativa canónica.\n\n**A nivel diocesano:**\n\n- Cada diócesis debe contar con un **consejo diocesano** de prevención, que asesora al obispo en la recepción de denuncias, el apoyo a las víctimas y los programas de prevención.\n- Cada diócesis debe designar una **persona responsable de recibir denuncias**, disponible de forma permanente.\n\nLas congregaciones religiosas tienen sus propias instancias. Los datos de contacto se publican en el sitio de cada diócesis y en el sitio nacional de prevención."),
       ("Normas, estándares y orientaciones",
        "Las consideraciones finales del ISE ordenan el sistema en cuatro piezas:\n\n| Pieza | Qué es | Ejemplos |\n|---|---|---|\n| **Estructura** | Las personas y organismos responsables | Consejo nacional, departamento, consejos diocesanos, responsables de denuncias |\n| **Normas** | Lo que obliga jurídicamente | Código de Derecho Canónico, normas de la Santa Sede sobre delitos graves, *Vos estis lux mundi*, protocolo y líneas guía *Cuidado y Esperanza* |\n| **Estándares** | Prácticas concretas de prevención | *Buenas Prácticas para ambientes sanos y seguros en la Iglesia* |\n| **Orientaciones** | Criterios de conducta y formación | El ISE; la formación de clérigos, consagrados y laicos |\n\nA esto se suman siempre las **leyes del Estado**: el ISE recuerda que, cuando hay delitos, deben seguirse las normas correspondientes y cooperar con las autoridades civiles.\n\nUn dato de actualización: el ISE cita *Vos estis lux mundi* en su versión de 2019; el papa Francisco promulgó en 2023 la versión definitiva, que entre otras cosas pide a cada diócesis un organismo u oficina de fácil acceso para recibir informes."),
       ("Lo que te toca a ti",
        "1. **Fórmate:** haz el curso de prevención de tu diócesis y renuévalo cuando corresponda.\n2. **Conoce los documentos:** el ISE, *Cuidado y Esperanza* y las *Buenas Prácticas*.\n3. **Ten los contactos:** responsable diocesano de denuncias, encargado de prevención de tu parroquia o colegio, y teléfonos de emergencia.\n4. **Aplica:** que cada actividad de tu grupo cumpla las buenas prácticas y el protocolo diocesano.\n5. **Difunde:** que las familias y los jóvenes sepan que existen estas normas y a quién acudir.\n\nUna comunidad donde todos conocen las reglas y los canales es un lugar mucho más difícil para quien quiera hacer daño.\n\n" + NOTA_VIGENCIA)],
      ("«Aquí nunca ha pasado nada»",
       "Una capilla rural organiza su primera misión de verano con adolescentes. Cuando una mamá pregunta qué medidas de cuidado habrá, el coordinador responde: «Señora, aquí nos conocemos todos y nunca ha pasado nada. Esos cursos son para las ciudades grandes». Ningún monitor ha hecho la formación en prevención y nadie conoce al responsable diocesano.",
       ["¿Qué estándares de la orientación 13 se incumplen?", "¿Por qué «nos conocemos todos» no es una medida de prevención?", "¿Qué debería tener resuelto la comunidad antes de la misión?"]),
      [["Política de prevención", "Conjunto de estructuras, normas, estándares y orientaciones con que la Iglesia busca impedir los abusos y responder a ellos."], ["Buenas Prácticas", "Documento de la Conferencia Episcopal de Chile que sistematiza prácticas concretas para ambientes sanos y seguros."], ["Responsable diocesano de denuncias", "Persona designada en cada diócesis para recibir denuncias, disponible de modo permanente."]],
      ("Efesios 5,8-13 · Caminen como hijos de la luz",
       "Pablo pide vivir como hijos de la luz, cuyo fruto es bondad, justicia y verdad, y no participar en las obras de las tinieblas, sino ponerlas en evidencia: todo lo que se saca a la luz queda manifiesto."),
      ("¿Tu comunidad vive la prevención como una carga o como una forma de amar?", "Pide por quienes trabajan en la prevención y en el acompañamiento de las víctimas.", "Esta semana, averigua y anota los contactos de prevención y denuncia de tu diócesis."),
      [ise("orientación 13 y consideraciones finales", "Pide participar en la formación en prevención, conocer los documentos que rigen los casos de abuso y cumplir las Buenas Prácticas; y describe las estructuras nacionales y diocesanas, las normas y los estándares que sostienen esa política."),
       C_CYE, C_VELM],
      ["¿Has hecho la formación en prevención de tu diócesis? ¿Y tu equipo?", "¿Conoce tu comunidad a su encargado de prevención?", "¿Qué documento de los mencionados no conocías?", "¿Cómo se informa a las familias de las medidas de cuidado?"],
      "Preparen la **ficha de prevención** de su comunidad: una hoja con los documentos vigentes, los contactos (encargado local, responsable diocesano de denuncias, consejo diocesano, emergencias), la lista de agentes pastorales con la fecha de su formación en prevención y las medidas de cuidado para las actividades. Publíquenla en la secretaría y compártanla con las familias.",
      ["Lee en el ISE la orientación 13 y las consideraciones finales.", "Busca en el sitio de tu diócesis el canal de denuncias y el curso de prevención.", "Revisa qué miembros de tu equipo no tienen la formación.", "Prepara la ficha de prevención."],
      "Señor, luz del mundo, que no quieres que nada quede oculto: da a tu Iglesia estructuras que protejan, pastores que respondan y comunidades despiertas. Que la prevención sea entre nosotros una forma concreta de amar. Amén.",
      "Prevenir es amar con anticipación.",
      ("Qué preguntar antes de inscribir a un hijo en una actividad pastoral",
       "Las familias tienen derecho a saber: ¿quiénes son los adultos responsables y qué formación en prevención tienen?, ¿cuántos adultos habrá?, ¿cómo se duerme y se usan los baños?, ¿cómo se comunicarán con los jóvenes?, ¿a quién aviso si algo me preocupa? Una comunidad que cumple la orientación 13 responde estas preguntas sin incomodarse, y las agradece."),
      [R_ISE, R_PREV, ("Cuidado y Esperanza. Líneas Guía de la CECh", CYE, "Normas de los obispos de Chile para tratar los casos de abuso sexual a menores."),
       ("Vos estis lux mundi (2023)", VELM, "Norma universal sobre la recepción de informes y la responsabilidad de las autoridades.")]),
]

E_P2 = [
    q("¿Cómo pide el estándar 9.c que se ejerza la autoridad?", ["Con firmeza y sin dar explicaciones.", "Con prudencia, como servicio y sin beneficio propio.", "Solo por quienes tienen más años en la comunidad."], 1, "Es la medida del Evangelio: el que quiera ser grande, que sirva."),
    q("¿Qué promueve expresamente el estándar 9.d?", ["La participación de la mujer y de la vocación laical en las instancias eclesiales y de decisión.", "Que los laicos se limiten a tareas prácticas.", "Que las decisiones se tomen siempre en secreto."], 0, "No solo colaborar: estar donde se decide."),
    q("¿Qué pide el ISE frente al culto a la persona?", ["Fomentarlo si el líder es bueno.", "Evitarlo, hacia uno mismo o hacia otros, y corregirlo cuando aparece.", "Ignorarlo, porque es inevitable."], 1, "Estándar 9.f; su antídoto es la corrección fraterna (9.g)."),
    q("Según la orientación 10, ¿quién es responsable de cuidar el límite en una relación asimétrica?", ["La persona con menos poder.", "Quien tiene más poder.", "Nadie; depende de las circunstancias."], 1, "A mayor diferencia de poder, menor capacidad del otro para decir que no."),
    q("¿Qué pide el estándar 10.d cuando una relación de servicio se vuelve insegura o ineficaz?", ["Manejarla a solas con discreción.", "Resolverla dialogando con un tercero.", "Esperar a que pase."], 1, "Nadie se cuida solo ni es buen juez de sí mismo."),
    q("¿Dónde pide el estándar 11.d que se realice el servicio?", ["En lugares seguros, abiertos y visibles.", "En espacios privados, para dar confianza.", "En la casa del agente pastoral."], 0, "No en espacios restringidos o solitarios."),
    q("¿Qué criterio da el ISE para el uso de redes sociales (11.h)?", ["Están prohibidas para los agentes pastorales.", "Usarlas con los mismos criterios que la relación presencial.", "Son un espacio privado sin reglas."], 1, "Lo que no haría en persona, tampoco por mensajes."),
    q("¿Qué establece el estándar 11.i sobre el alcohol?", ["Se puede consumir con moderación ante menores.", "No ofrecerlo a menores o personas vulnerables ni consumirlo en su presencia.", "Solo se prohíbe en la misa."], 1, "Incluye campamentos, misiones y celebraciones del grupo."),
    q("¿Qué pide el estándar 12.e a quien acompaña a otros?", ["Que no necesite ayuda de nadie.", "Que reciba acompañamiento espiritual frecuente y supervisión.", "Que acompañe al mayor número posible de personas."], 1, "Nadie acompaña bien si no es acompañado."),
    q("¿Qué debe tener cada diócesis, según las consideraciones finales del ISE?", ["Un consejo de prevención y una persona responsable de recibir denuncias, disponible de modo permanente.", "Solo un buzón de sugerencias.", "Nada; depende de cada parroquia."], 0, "Además de las instancias nacionales: el Consejo Nacional y el Departamento de Prevención de Abusos."),
]

T_P2 = ("Trabajo final de la parte 2: el plan de ambientes sanos de tu comunidad. Entrega: el resultado de la evaluación anónima de la autoridad con dos cambios acordados; "
        "el mapa de poder del grupo con sus resguardos; el recorrido de los espacios pastorales con las mejoras propuestas; el registro de derivación; y la ficha de prevención "
        "con contactos y estado de formación del equipo. Preséntalo al párroco o al encargado de prevención de tu comunidad.")
